class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        s = side
        P = 4 * s  # perimeter

        # Map each boundary point to its arc-length coordinate t in [0, P).
        # Order: bottom (0,0)->(s,0), right (s,0)->(s,s),
        #        top (s,s)->(0,s), left (0,s)->(0,0).
        ts = []
        for x, y in points:
            if y == 0:
                t = x
            elif x == s:
                t = s + y
            elif y == s:
                t = 2 * s + (s - x)
            else:  # x == 0
                t = 3 * s + (s - y)
            ts.append(t)
        ts.sort()
        n = len(ts)

        # Feasibility: can we pick k points with pairwise circular distance >= d?
        # Valid because for d <= side, Manhattan >= d  <=>  circular arc >= d.
        def ok(d: int) -> bool:
            # nxt[i] = first index j with ts[j] >= ts[i] + d  (always > i)
            nxt = [0] * n
            j = 0
            for i in range(n):
                if j < i + 1:
                    j = i + 1
                limit = ts[i] + d
                while j < n and ts[j] < limit:
                    j += 1
                nxt[i] = j
            # Try every point as the smallest-t selected point.
            for i in range(n - k + 1):
                cnt = 1
                cur = i
                while cnt < k:
                    cur = nxt[cur]
                    if cur >= n:
                        break
                    cnt += 1
                if cnt == k and ts[i] + P - ts[cur] >= d:
                    return True
            return False

        # Answer <= P / k (pigeonhole on arc gaps), and P/k <= side since k >= 4.
        lo, hi = 0, P // k
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if ok(mid):
                lo = mid
            else:
                hi = mid - 1
        return lo

import sys

def solve():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    it = iter(data)
    N = int(next(it))
    adj = [[] for _ in range(N + 1)]
    for _ in range(N - 1):
        a = int(next(it)); b = int(next(it))
        adj[a].append(b)
        adj[b].append(a)

    NEG = -10**9

    # Root tree at 1, build parent and traversal order iteratively
    parent = [0] * (N + 1)
    parent[1] = -1
    order = []
    stack = [1]
    while stack:
        u = stack.pop()
        order.append(u)
        for v in adj[u]:
            if v != parent[u]:
                parent[v] = u
                stack.append(v)

    # dp[u][k][h]: max selected vertices in connected selected set inside u's
    # subtree that includes u, with exactly k selected children, where h=1 means
    # a degree-4 vertex already exists among u's selected descendants (not u).
    dp = [None] * (N + 1)
    ans = NEG

    for u in reversed(order):
        # knapsack merge over children: cur[m][h]
        cur = [[NEG, NEG] for _ in range(5)]
        cur[0][0] = 0
        for v in adj[u]:
            if v == parent[u]:
                continue
            d = dp[v]
            # child included => its parent (u) is selected, so child needs
            # selected-child-count 0 (degree 1) or 3 (degree 4)
            inc0 = d[0][0]                       # child degree 1, no deg-4 below
            inc1 = max(d[0][1], d[3][0], d[3][1])  # deg-4 at/below child
            nxt = [[NEG, NEG] for _ in range(5)]
            for m in range(5):
                for h in range(2):
                    val = cur[m][h]
                    if val == NEG:
                        continue
                    # exclude child
                    if val > nxt[m][h]:
                        nxt[m][h] = val
                    # include child
                    if m < 4:
                        if inc0 != NEG:
                            nv = val + inc0
                            if nv > nxt[m + 1][h]:
                                nxt[m + 1][h] = nv
                        if inc1 != NEG:
                            nv = val + inc1
                            if nv > nxt[m + 1][1]:
                                nxt[m + 1][1] = nv
            cur = nxt

        d = [[NEG, NEG] for _ in range(5)]
        for k in range(5):
            for h in range(2):
                if cur[k][h] != NEG:
                    d[k][h] = cur[k][h] + 1  # include u itself
        dp[u] = d

        # u as highest node of the alkane (parent not selected):
        # degree of u = k must be 1 or 4; need a degree-4 vertex somewhere.
        if d[1][1] > ans:
            ans = d[1][1]
        if d[4][0] > ans:
            ans = d[4][0]
        if d[4][1] > ans:
            ans = d[4][1]

    print(ans if ans != NEG else -1)

