        n = len(M)
        R = [[1 if i == j else 0 for j in range(n)] for i in range(n)]
        B = [row[:] for row in M]
        while e:
            if e & 1:
                R = matmul(R, B)
            e >>= 1
            if e:
                B = matmul(B, B)
        return R

